import type { Argv, ArgumentsCamelCase } from 'yargs'
import { CICD_OPERATIONS } from './operations'
import { createOperationCommand } from './command-builder'
import type { CicdOperation } from './types'

/** Register one operation directly under the given yargs level. */
function addOperation(y: Argv, operation: CicdOperation): Argv {
    return y.command(createOperationCommand(operation))
}

/** Register a group (e.g. `testsuite`) with its member operations as subcommands. */
function addGroup(y: Argv, group: string, operations: CicdOperation[]): Argv {
    return y.command({
        command: `${group} <command>`,
        describe: `sn_cicd ${group} operations`,
        builder: (sub: Argv) => {
            const withMembers = operations.reduce(addOperation, sub)
            return withMembers.demandCommand()
        },
        handler: () => {},
    })
}

export function builder(yargs: Argv) {
    // Each operation either sits directly under `cicd` or nests under a named group — declared
    // explicitly per operation via `group`, not inferred from the command's shape. Ungrouped
    // operations (install/publish/rollback) register directly; grouped ones (testsuite/tests) are
    // collected so each group registers once with all its members as subcommands.
    const ungrouped = CICD_OPERATIONS.filter((operation) => !operation.group)
    const groups = new Map<string, CicdOperation[]>()
    for (const operation of CICD_OPERATIONS) {
        if (operation.group) {
            const members = groups.get(operation.group) ?? []
            members.push(operation)
            groups.set(operation.group, members)
        }
    }

    let y = ungrouped.reduce(addOperation, yargs)
    for (const [group, operations] of groups) {
        y = addGroup(y, group, operations)
    }
    return y.demandCommand()
}

export function handler(_args: ArgumentsCamelCase): void {
    // no-op: all behavior lives in the namespace/operation subcommands
}
